namespace FileFormat.Zpaq;

/// <summary>
/// The LZ77 / BWT preprocessor of ZPAQ methods 1..3 (the <c>x</c> method's second argument),
/// presented as a byte source the compressor reads.
/// </summary>
/// <remarks>
/// <para>Converted from libzpaq 7.15 (Matt Mahoney, public domain), class <c>LZBuffer</c>.</para>
/// <para>
/// Level 1 emits bit-packed LZ77 codes, level 2 byte-aligned LZ77 codes, level 3 the
/// Burrows-Wheeler transform with the end-of-string position in the last four bytes. The
/// matching PCOMP programs that undo each of these are generated by
/// <see cref="ZpaqMethods.MakeConfig"/>. The suffix array (for BWT and for the suffix-array
/// match finder) comes from <see cref="ZpaqSuffixArray"/>; a suffix array is unique, so the
/// output equals the reference's regardless of how it is built.
/// </para>
/// </remarks>
internal sealed class ZpaqLzBuffer : IZpaqReader {
  private const int BufSize = 1 << 14;

  private readonly uint[] _ht;
  private readonly byte[] _in;
  private readonly int _checkbits;
  private readonly int _level;
  private readonly uint _htsize;
  private readonly uint _n;
  private uint _i;
  private readonly uint _minMatch;
  private readonly uint _minMatch2;
  private readonly uint _maxMatch = BufSize * 3;
  private readonly uint _maxLiteral = BufSize / 4;
  private readonly uint _lookahead;
  private uint _h1, _h2;
  private readonly uint _bucket;
  private readonly int _shift1, _shift2;
  private readonly int _minMatchBoth;
  private readonly int _rb;
  private uint _bits;
  private int _nbits;
  private int _rpos, _wpos;
  private uint _idx;
  private readonly int[]? _sa;
  private readonly int _isaOffset = -1;
  private readonly byte[] _buf = new byte[BufSize];

  /// <summary>Prepares to encode <paramref name="input"/> with method arguments <paramref name="args"/>.</summary>
  public ZpaqLzBuffer(ZpaqBuffer input, int[] args) {
    // A private copy with zero padding: the hash match finder peeks a few bytes past the
    // end (the reference reads its buffer's slack there), and E8E9 must not touch the caller's data.
    this._n = (uint)input.Size;
    this._in = new byte[input.Size + 8];
    input.Span.CopyTo(this._in);
    this._level = args[1] & 3;
    this._minMatch = (uint)args[2];
    this._minMatch2 = (uint)args[3];
    this._lookahead = (uint)args[6];
    this._bucket = (1u << args[4]) - 1;
    this._shift1 = this._minMatch > 0 ? (args[5] - 1) / (int)this._minMatch + 1 : 1;
    this._shift2 = this._minMatch2 > 0 ? (args[5] - 1) / (int)this._minMatch2 + 1 : 0;
    this._minMatchBoth = (int)Math.Max(this._minMatch, this._minMatch2 + this._lookahead) + 4;
    this._rb = args[0] > 4 ? args[0] - 4 : 0;
    var useSa = args[5] - args[0] >= 21;
    this._checkbits = useSa ? 17 + args[0] : 12 - args[0];

    if ((this._minMatch < 4 && this._level == 1) || (this._minMatch < 1 && this._level == 2))
      ZpaqError.Throw("match length $3 too small");

    if (args[1] > 4)
      ZpaqMethods.E8E9(this._in.AsSpan(0, (int)this._n));

    if (this._level == 3) {
      this._ht = [];
      this._sa = ZpaqSuffixArray.Build(this._in.AsSpan(0, (int)this._n));
    } else if (useSa) {
      this._sa = ZpaqSuffixArray.Build(this._in.AsSpan(0, (int)this._n));
      this._ht = new uint[1u << 17 << args[0]];
      this._isaOffset = 0;
    } else
      this._ht = new uint[1u << args[5]];
    this._htsize = (uint)this._ht.Length;
  }

  /// <inheritdoc/>
  public int Get() {
    var c = -1;
    if (this._rpos == this._wpos)
      this.Fill();
    if (this._rpos < this._wpos)
      c = this._buf[this._rpos++];
    if (this._rpos == this._wpos)
      this._rpos = this._wpos = 0;
    return c;
  }

  /// <inheritdoc/>
  public int Read(Span<byte> p) {
    if (this._rpos == this._wpos)
      this.Fill();
    var nr = Math.Min(p.Length, this._wpos - this._rpos);
    this._buf.AsSpan(this._rpos, nr).CopyTo(p);
    this._rpos += nr;
    if (this._rpos == this._wpos)
      this._rpos = this._wpos = 0;
    return nr;
  }

  private static int Lg(uint x) => x == 0 ? 0 : 32 - System.Numerics.BitOperations.LeadingZeroCount(x);

  private void PutBits(uint x, int k) {
    x &= (uint)((1L << k) - 1);
    this._bits |= x << this._nbits;
    this._nbits += k;
    while (this._nbits > 7) {
      this._buf[this._wpos++] = (byte)this._bits;
      this._bits >>= 8;
      this._nbits -= 8;
    }
  }

  private void FlushBits() {
    if (this._nbits > 0)
      this._buf[this._wpos++] = (byte)this._bits;
    this._bits = 0;
    this._nbits = 0;
  }

  private void Put(int c) => this._buf[this._wpos++] = (byte)c;

  private void Fill() {
    var input = this._in;
    var n = this._n;

    if (this._level == 3) {
      var sa = this._sa!;
      for (; this._wpos < BufSize && this._i < n + 5; ++this._i) {
        if (this._i == 0)
          this.Put(n > 0 ? input[n - 1] : 255);
        else if (this._i > n) {
          this.Put((int)(this._idx & 255));
          this._idx >>= 8;
        } else if (sa[this._i - 1] == 0) {
          this._idx = this._i;
          this.Put(255);
        } else
          this.Put(input[sa[this._i - 1] - 1]);
      }
      return;
    }

    var lit = 0u;
    var mask = (uint)((1L << this._checkbits) - 1);
    var ht = this._ht;
    while (this._i < n && this._wpos * 2 < BufSize) {
      var i = this._i;
      var blen = this._minMatch - 1;
      var bp = 0u;
      var blit = 0u;
      var bscore = 0;

      if (this._isaOffset >= 0) {
        var sa = this._sa!;
        if ((uint)sa[ht[i & mask]] != i)
          for (var j = 0u; j < n; ++j)
            if (((uint)sa[j] & ~mask) == (i & ~mask))
              ht[(uint)sa[j] & mask] = j;
        for (var h = 0u; h <= this._lookahead; ++h) {
          var q = ht[(h + i) & mask];
          if ((uint)sa[q] != h + i)
            continue;
          for (var j = -1; j <= 1; j += 2) {
            for (var k = 1u; k <= this._bucket; ++k) {
              var qq = (uint)(q + j * (long)k);
              uint p;
              if (qq < n && (p = (uint)sa[qq] - h) < i) {
                uint l, l1;
                for (l = h; i + l < n && l < this._maxMatch && input[p + l] == input[i + l]; ++l) { }
                for (l1 = h; l1 > 0 && input[p + l1 - 1] == input[i + l1 - 1]; --l1) { }
                var score = (int)(l - l1) * 8 - Lg(i - p) - 4 * (lit == 0 && l1 > 0 ? 1 : 0) - 11;
                for (var a = 0u; a < h; ++a)
                  score = score * 5 / 8;
                if (score > bscore) {
                  blen = l;
                  bp = p;
                  blit = l1;
                  bscore = score;
                }
                if (l < blen || l < this._minMatch || l > 255)
                  break;
              }
            }
          }
          if (bscore <= 0 || blen < this._minMatch)
            break;
        }
      } else if (this._level == 1 || this._minMatch <= 64) {
        if (this._minMatch2 > 0) {
          for (var k = 0u; k <= this._bucket; ++k) {
            var p = ht[this._h2 ^ k];
            if (p != 0 && (p & mask) == (input[i + 3] & mask)) {
              p >>= this._checkbits;
              if (p < i && i + blen <= n && (blen == 0 || input[p + blen - 1] == input[i + blen - 1])) {
                uint l;
                for (l = this._lookahead; i + l < n && l < this._maxMatch && input[p + l] == input[i + l]; ++l) { }
                if (l >= this._minMatch2 + this._lookahead) {
                  int l1;
                  for (l1 = (int)this._lookahead; l1 > 0 && input[p + l1 - 1] == input[i + l1 - 1]; --l1) { }
                  var score = (int)(l - (uint)l1) * 8 - Lg(i - p) - 8 * (lit == 0 && l1 > 0 ? 1 : 0) - 11;
                  if (score > bscore) {
                    blen = l;
                    bp = p;
                    blit = (uint)l1;
                    bscore = score;
                  }
                }
              }
            }
            if (blen >= 128)
              break;
          }
        }

        if (this._minMatch2 == 0 || blen < this._minMatch2) {
          for (var k = 0u; k <= this._bucket; ++k) {
            var p = ht[this._h1 ^ k];
            if (p != 0 && i + 3 < n && (p & mask) == (input[i + 3] & mask)) {
              p >>= this._checkbits;
              if (p < i && i + blen <= n && (blen == 0 || input[p + blen - 1] == input[i + blen - 1])) {
                uint l;
                for (l = 0; i + l < n && l < this._maxMatch && input[p + l] == input[i + l]; ++l) { }
                var score = (int)l * 8 - Lg(i - p) - 2 * (lit > 0 ? 1 : 0) - 11;
                if (score > bscore) {
                  blen = l;
                  bp = p;
                  blit = 0;
                  bscore = score;
                }
              }
            }
            if (blen >= 128)
              break;
          }
        }
      }

      var off = i - bp;
      var extra = this._level == 2 ? (off >= 1 << 16 ? 1u : 0u) + (off >= 1 << 24 ? 1u : 0u) : 0u;
      if (off > 0 && bscore > 0 && blen - blit >= this._minMatch + extra) {
        lit += blit;
        this.WriteLiteral(i + blit, ref lit);
        this.WriteMatch(blen - blit, off);
      } else {
        blen = 1;
        ++lit;
      }

      if (this._isaOffset >= 0)
        this._i += blen;
      else {
        while (blen-- > 0) {
          i = this._i;
          if (i + this._minMatchBoth < n) {
            var ih = ((i * 1234547u) >> 19) & this._bucket;
            var p = (i << this._checkbits) | (input[i + 3] & mask);
            if (this._minMatch2 != 0) {
              ht[this._h2 ^ ih] = p;
              this._h2 = (((this._h2 * 9) << this._shift2) + (input[i + this._minMatch2 + this._lookahead] + 1u) * 23456789u) & (this._htsize - 1);
            }
            ht[this._h1 ^ ih] = p;
            this._h1 = (((this._h1 * 5) << this._shift1) + (input[i + this._minMatch] + 1u) * 123456791u) & (this._htsize - 1);
          }
          ++this._i;
        }
      }

      if (lit >= this._maxLiteral)
        this.WriteLiteral(this._i, ref lit);
    }

    if (this._i == n) {
      this.WriteLiteral(n, ref lit);
      this.FlushBits();
    }
  }

  private void WriteLiteral(uint i, ref uint lit) {
    var input = this._in;
    if (this._level == 1) {
      if (lit < 1)
        return;
      var ll = Lg(lit);
      this.PutBits(0, 2);
      --ll;
      while (--ll >= 0) {
        this.PutBits(1, 1);
        this.PutBits((lit >> ll) & 1, 1);
      }
      this.PutBits(0, 1);
      while (lit != 0)
        this.PutBits(input[i - lit--], 8);
      return;
    }
    while (lit > 0) {
      var lit1 = Math.Min(lit, 64u);
      this.Put((int)lit1 - 1);
      for (var j = i - lit; j < i - lit + lit1; ++j)
        this.Put(input[j]);
      lit -= lit1;
    }
  }

  private void WriteMatch(uint len, uint off) {
    if (this._level == 1) {
      var ll = Lg(len) - 1;
      off += (1u << this._rb) - 1;
      var lo = Lg(off) - 1 - this._rb;
      this.PutBits((uint)(lo + 8) >> 3, 2);
      this.PutBits((uint)lo & 7, 3);
      while (--ll >= 2) {
        this.PutBits(1, 1);
        this.PutBits((len >> ll) & 1, 1);
      }
      this.PutBits(0, 1);
      this.PutBits(len & 3, 2);
      this.PutBits(off, this._rb);
      this.PutBits(off >> this._rb, lo);
      return;
    }
    --off;
    var minMatch = this._minMatch;
    while (len > 0) {
      var len1 = len > minMatch * 2 + 63 ? minMatch + 63 : len > minMatch + 63 ? len - minMatch : len;
      if (off < 1 << 16) {
        this.Put((int)(64 + len1 - minMatch));
        this.Put((int)(off >> 8));
        this.Put((int)off);
      } else if (off < 1 << 24) {
        this.Put((int)(128 + len1 - minMatch));
        this.Put((int)(off >> 16));
        this.Put((int)(off >> 8));
        this.Put((int)off);
      } else {
        this.Put((int)(192 + len1 - minMatch));
        this.Put((int)(off >> 24));
        this.Put((int)(off >> 16));
        this.Put((int)(off >> 8));
        this.Put((int)off);
      }
      len -= len1;
    }
  }
}
